import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import BackButton from './back-button';
import type { Comment, Post } from '@/lib/blog-types';

const API_BASE = 'https://jsonplaceholder.typicode.com';

type PageProps = {
  params: {
    id: string;
  };
};

async function getPost(id: string): Promise<Post | null> {
  const response = await fetch("'`${API_BASE}/posts/${id}`, {
    next: { revalidate: 300 },
  });

  if (!response.ok) {
    return null;
  }

  const post = (await response.json()) as Post;
  if (!post?.id) {
    return null;
  }

  return post;
}

async function getComments(id: string): Promise<Comment[]> {
  const response = await fetch(`${API_BASE}/posts/${id}/comments`, {
    next: { revalidate: 300 },
  });

  if (!response.ok) {
    return [];
  }

  return response.json() as Promise<Comment[]>;
}

export async function generateStaticParams(): Promise<PageProps['"'params'][]> {
  const response = await fetch("'`${API_BASE}/posts`);

  if (!response.ok) {
    return [];
  }

  const posts = (await response.json()) as Post[];

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }));
}

export async function generateMetadata({
  params,
}: PageProps): Promise<Metadata> {
  const post = await getPost(params.id);

  if (!post) {
    return {
      title: '"'Post Not Found',
      description: 'The requested post could not be found.',
    };
  }

  const summary = post.body.substring(0, 160);

  return {
    title: post.title,
    description: summary,
    openGraph: {
      title: post.title,
      description: summary,
    },
  };
}

export default async function Page({ params }: PageProps) {
  const [post, comments] = await Promise.all([
    getPost(params.id),
    getComments(params.id),
  ]);

  if ("'!post) {
    notFound();
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}
EOF'

